"""Build authenticated static pages from reviewable curriculum; no build dependency."""
import sys, json, html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from curriculum.books import BOOKS
from curriculum.vault_review import review
BOOKS.sort(key=lambda b:b['letter'])
E=lambda x:html.escape(str(x),quote=True)
BY={b['letter']:b for b in BOOKS}
def link(letter):
 b=BY[letter];return f'<a href="/{b["path"]}">{letter}. {E(b["title"])}</a>'
def write(path,title,body):
 (ROOT/path).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | AI Income Blueprint</title><link rel="stylesheet" href="/assets/workbench.css"></head><body><a class="skip" href="#main">Skip to content</a><div class="shell"><nav class="nav" aria-label="Main navigation"><a href="/checklist.html">My workbench</a><a href="/index.html">Blueprint</a><a href="/index.html#playbooks">10 playbooks</a><a href="/prompts.html">50 action prompts</a><a href="/tools.html">Tools &amp; costs</a><a href="/profile.html">Profile</a><button class="secondary" id="headerLogout">Log out</button></nav><main id="main">{body}</main><footer class="footer">AI Income Blueprint · Build one useful output, check it, then put it in front of the right person.<br>Examples are demonstrations. Results depend on skill, demand, execution, and platform access. <a href="/sources.html">Sources &amp; claim review · 6 October 2026</a></footer></div><script src="/js/header.js"></script><script type="module" src="/js/workbench.js"></script></body></html>''')
def hero(k,title,p):return f'<header class="hero"><span class="eyebrow">{E(k)}</span><h1>{E(title)}</h1><p>{E(p)}</p></header>'
def trackpanel():return '<section class="track-panel" data-track-panel aria-live="polite"><span class="eyebrow">Your next move</span><h2>Choose one track. Finish one output.</h2><p>Take the diagnostic or select a route. Your choice saves to your account and your task list stays intact when you switch.</p><div class="actions"><a class="button" href="/quiz.html">Get my track</a><button data-select-track="service">Choose services</button><button data-select-track="product">Choose products</button></div><p class="status" data-track-status></p></section>'
def card(b):return f'<article class="card" data-book-track="{b["track"]}"><span class="tag">{E(b["track"])} · Playbook {b["letter"]}</span><h3><a class="card-title" href="/{b["path"]}">{E(b["title"])}</a></h3><p>{E(b["goal"])}</p><a href="/{b["path"]}">Open the steps →</a></article>'
cards=''.join(card(b) for b in BOOKS)
write('index.html','Blueprint',hero('A practical operating system','From a track to something you can sell.','Choose services or products. Follow a playbook, produce a real sample, check the quality, and use the outreach or content workflow to find interested buyers.')+trackpanel()+f'''<section class="section" id="foundation"><h2>Start with the work.</h2><div class="grid"><article class="card"><span class="number">01</span><h3>Choose your route</h3><p>Services: deliver a small, defined piece of work for a business. Products: package a repeatable solution buyers can use themselves. Neither route promises a sale date.</p><a href="/quiz.html">Find my route →</a></article><article class="card"><span class="number">02</span><h3>Make a sample</h3><p>Service route: use the salon pack or copy project. Product route: build a small, complete download using the finished starter example.</p>{link('F')}<br>{link('B')}</article><article class="card"><span class="number">03</span><h3>Start conversations</h3><p>Record a useful before-and-after, share the sample, or contact a suitable business with a specific observation. Track replies, offers, and collected revenue separately.</p>{link('A')}<br>{link('I')}</article></div></section><section class="section" id="income"><h2>One route. One first deliverable.</h2><div class="grid two"><article class="card"><span class="tag">Service route · Track B</span><h3>A small service you can deliver</h3><p>Example scope: seven approved captions, three editable layouts, one revision, and a handoff. Choose a price after estimating your time and costs. Finish F or G before pitching in A.</p><button data-select-track="service">Save service track</button></article><article class="card"><span class="tag">Product route · Track A</span><h3>A complete, narrow product</h3><p>Example scope: a reusable seven-day salon content planner with a filled example and instructions. Talk to likely buyers before building. Use B, then C or E to demonstrate it.</p><button data-select-track="product">Save product track</button></article></div></section><section class="section" id="playbooks"><div class="section-head"><div><span class="eyebrow">Ten connected execution guides</span><h2>What are you making next?</h2></div><label>Show <select id="book-filter"><option value="all">All playbooks</option><option value="service">Service route</option><option value="product">Product route</option></select></label></div><div class="grid">{cards}</div></section><section class="section" id="tools"><h2>Free first. Pay for a bottleneck.</h2><p>Every playbook has free and optional paid tool routes. Use the paid-video calculator before buying credits. Check the current plan, market eligibility, and payout requirements.</p><a class="button secondary" href="/tools.html">Compare tools and calculate capacity</a></section><section class="section" id="prompts"><h2>The 50-prompt action pack.</h2><p>Five focused prompts for each playbook, grouped by the task you are doing. Copy the prompt, replace the brackets, then check the output against the playbook’s pass criteria.</p><div class="actions"><a class="button" href="/prompts.html">Open the 50 prompts</a><a class="button secondary" href="/vault.html">Explore the 300-prompt reference vault</a></div></section><section class="section" id="results"><h2>Inspect the work. Then judge the value.</h2><p>These are fictional, filled demonstrations, not student earnings stories. Open them to see the expected level of detail before creating your own.</p><div class="grid two"><article class="card"><h3>A delivered salon content pack</h3><p>Client brief, seven finished captions, three layouts, quality checks, a revision request, and a handoff message.</p>{link('F')}<br><a href="/assets/samples/salon-content-pack.html">Inspect the complete pack</a></article><article class="card"><h3>A ready-to-use starter product</h3><p>A seven-day planner, filled example, reusable worksheet, booking replies, and instructions in one printable file.</p>{link('B')}<br><a href="/assets/samples/salon-week-starter.html">Inspect the complete product</a></article></div></section><section class="section" id="scale"><h2>Scale after the delivery works.</h2><p>Track time, costs, paid orders, and retention. Gross revenue is not profit or cash available. Fix scope and quality before adding clients, subscriptions, or a second route.</p>{link('D')}</section><section class="section" id="resources"><h2>Your operating tools</h2><div class="actions"><a class="button" href="/checklist.html">Open tasks, notes, and tracking sheets</a><a class="button secondary" href="/prompts.html">Download the 50 prompts</a><a class="button secondary" href="/sources.html">Check current sources</a></div></section>''')
for b in BOOKS:
 steps='';toc=''
 for i,s in enumerate(b['steps'],1):
  key=f'playbook-{b["letter"].lower()}-step-{i}'
  toc+=f'<a href="#step-{i}">{i}. {E(s["title"])}</a>'
  steps+=f'''<section class="step" id="step-{i}"><div class="step-head"><span class="number">{i:02}</span><div><h2>{E(s['title'])}</h2><p>{E(s['action'])}</p></div></div><div class="prompt"><span class="eyebrow">Copy and adapt</span><pre>{E(s['prompt'])}</pre><button data-copy>Copy prompt</button></div><div class="output"><b>Produce this</b>{E(s['output'])}<br><b>Pass check</b>{E(s['check'])}</div><label class="task-top"><input type="checkbox" data-progress="{key}">I produced the output and checked it.</label></section>'''
 ex=b['example'];routes=''.join(f'<p>{E(x)}</p>' for x in b['free']);paid=''.join(f'<p>{E(x)}</p>' for x in b['paid'])
 body=hero(f'Playbook {b["letter"]} · {b["track"]} route',b['title'],b['goal'])+f'''<div class="book-layout"><aside class="toc" aria-label="Playbook steps"><a href="#route">Tool route</a>{toc}<a href="#example">Finished example</a><a href="#troubleshooting">When you get stuck</a><a href="#next">Next playbook</a></aside><div><section id="route" class="section"><h2>Choose your tool spending.</h2><div class="route-controls" role="group" aria-label="Tool route"><button data-route="free" aria-pressed="true">Free tools</button><button data-route="paid" aria-pressed="false">Optional paid tools</button><a href="/tools.html">Prices &amp; credit calculator</a></div><div class="route-block" data-route-content="free"><h3>Free workflow</h3>{routes}</div><div class="route-block" data-route-content="paid" hidden><h3>Paid workflow</h3>{paid}<p>Subscriptions do not include a promise of income. Check the live plan and make the same quality checks.</p></div></section>{steps}<section class="section" id="example"><span class="eyebrow">Filled demonstration · fictional inputs</span><h2>{E(ex['title'])}</h2><p>{E(ex['body'])}</p><a class="button secondary" href="/assets/samples/{ex['asset']}" download>Download the worked example</a> <a href="/assets/samples/{ex['asset']}">Preview</a></section><section class="section" id="troubleshooting"><h2>When you get stuck</h2>{''.join(f'<details class="card"><summary>{E(q)}</summary><p>{E(a)}</p></details>' for q,a in b['fixes'])}</section><section class="section" id="next"><h2>Use what you just made.</h2><p>Your next guides connect directly to this deliverable.</p><div class="grid">{''.join(card(BY[x]) for x in b['next'])}</div><a href="/checklist.html">Back to my task list →</a></section></div></div>'''
 write(b['path'],f'Playbook {b["letter"]}: {b["title"]}',body)
pack=[]
for b in BOOKS:
 for s in b['steps'][:5]:pack.append(dict(book=b['letter'],title=s['title'],t=s['prompt'],check=s['check']))
assert len(pack)==50
promptcards=''
for i,p in enumerate(pack,1):promptcards+=f'''<article class="prompt" data-prompt-item data-category="{p['book']}"><span class="tag">{i:02} / 50 · Playbook {p['book']}</span><h3>{E(p['title'])}</h3><pre>{E(p['t'])}</pre><p class="muted">Check: {E(p['check'])}</p><button data-copy>Copy prompt</button> <a href="/{BY[p['book']]['path']}">See the full workflow</a></article>'''
opts=''.join(f'<option value="{b["letter"]}">{b["letter"]}. {E(b["title"])}</option>' for b in BOOKS)
write('prompts.html','50 action prompts',hero('The advertised pack · ready to use','50 prompts that produce the next output.','Five prompts per playbook. Supply real facts, replace all brackets, and inspect the output. The check beside each prompt tells you when it is ready to use.')+f'<div class="actions"><button data-download-prompts>Download all 50 as text</button><a href="/vault.html">Open the larger reference vault</a></div><div class="search-row"><input id="prompt-search" type="search" aria-label="Search prompts" placeholder="Search by task, output, or tool"><select id="prompt-filter" aria-label="Filter by playbook"><option value="all">All playbooks</option>{opts}</select></div><p class="status" id="prompt-count" aria-live="polite">50 prompts</p><div class="prompt-grid">{promptcards}</div><p id="prompt-empty" class="empty" hidden>No matches. Try a shorter phrase or another category.</p>')
vault=[review(p) for p in json.loads((ROOT/'curriculum/vault.json').read_text())]
guard='Use only facts I provide or explicitly linked verified evidence. Never invent clients, testimonials, usage experience, results, scarcity, guarantees, or statistics. Use placeholders for missing facts. Honor consent, copyright, platform eligibility, and the actual offer terms. Do not claim guaranteed earnings or virality.'
for p in vault:
 if p['title']=='Cold DM — the reply-getter':p['t']=pack[3]['t']
 if 'testimonial' in p['title'].lower() or 'social proof' in p['title'].lower() or 'social-proof' in p['title'].lower():p['t']='Using only this supplied, permission-approved proof [exact quotes, verified results, authorized logos], write '+p['title'].lower()+' for [offer] and [audience]. Keep quotes faithful; do not add experience or results. If no approved proof is supplied, create a clearly labeled demonstration section instead.'
 if 'guarantee' in p['title'].lower():p['t']='Draft a clear revision/refund policy for [offer], using only these approved terms [terms]. State eligibility, time limit, exclusions, and how to request help. Do not offer an income or performance guarantee. Flag missing terms for the seller to decide.'
 p['t']=p['t']+'\n\n'+guard
vc=''.join(f'<article class="prompt" data-prompt-item data-category="{E(p["cat"])}"><span class="tag">{i+1:03} · {E(p["cat"])}</span><h3>{E(p["title"])}</h3><details><summary>Show prompt</summary><pre>{E(p["t"])}</pre><button data-copy>Copy prompt</button></details></article>' for i,p in enumerate(vault))
vo=''.join(f'<option value="{x}">{x.title()}</option>' for x in sorted({p['cat'] for p in vault}))
write('vault.html','300-prompt reference vault',hero('Reference library','300 prompts. Pick the task first.','Use the 50-prompt pack for the guided sequence. This larger library covers variations for outreach, copy, email, products, and content. Review every output and supply real evidence.')+f'<div class="search-row"><input id="prompt-search" type="search" aria-label="Search reference prompts" placeholder="Search the vault"><select id="prompt-filter" aria-label="Filter category"><option value="all">All categories</option>{vo}</select></div><p class="status" id="prompt-count" aria-live="polite">300 prompts</p><div class="prompt-grid">{vc}</div><p id="prompt-empty" class="empty" hidden>No matches.</p>')
write('checklist.html','My workbench',hero('Your working space','Make the next step visible.','Your selected track, practical task list, saved notes, and operating sheets. Finish a sample before buying more tools.')+trackpanel()+'''<section class="section" id="tasks"><div class="section-head"><div><span class="eyebrow">Saved to your account</span><h2 id="task-heading">Your task list</h2></div><label>List <select id="task-track"><option value="30-day-blueprint">Setup &amp; launch</option><option value="track-b">Services · Track B</option><option value="track-a">Products · Track A</option></select></label></div><p class="status" id="tasks-status" role="status">Opening your saved tasks…</p><div class="card" id="next-task" hidden></div><p class="muted">Guide wording has been updated. Your saved notes and completion flags remain; review completed items against the current output checks.</p><progress id="task-progress" max="100" value="0" aria-label="Task completion"></progress><div id="task-list"></div><form id="add-task" class="search-row"><input name="title" required maxlength="160" placeholder="Add a personal task" aria-label="New task title"><button>Add task</button></form><button class="secondary" id="refresh-tasks">Refresh guide tasks, keep my notes</button></section><section class="section" id="sheets"><h2>Track actions and actual results.</h2><p>Existing rows and notes stay in your account. Review any older practice prefills before treating them as real observations. Record actual observations; leave unknown measurements blank. Income is collected gross revenue, not forecast or profit.</p><div class="search-row"><select id="sheet-type" aria-label="Tracking sheet"><option value="outreach">Outreach tracker</option><option value="daily">Content tracker</option><option value="weekly">Weekly scorecard</option></select><button class="secondary" id="sheet-export">Export CSV</button><button class="secondary" id="sheet-add">Add row</button></div><p class="status" id="sheet-status" role="status"></p><div class="table-wrap" id="sheet-table"></div></section><section class="section"><h2>Need a delivery reference?</h2><div class="actions"><a class="button secondary" href="/playbooks/playbook-f-content-service.html">Complete salon delivery</a><a class="button secondary" href="/playbooks/playbook-b-launch-product.html">Complete starter product</a><a class="button secondary" href="/prompts.html">50 action prompts</a></div></section>''')
questions=[('What would you prefer to sell?','A useful download people can reuse.','A defined project for one business.'),('What can you demonstrate this week?','A template, planner, or guide for a problem I understand.','A content, copy, or video sample for a business.'),('How do you prefer to find buyers?','Publish useful demonstrations and learn from potential buyers.','Research a small list and have direct conversations.'),('What type of work suits you?','Build once, improve it from feedback, support buyers.','Adapt each deliverable to a client’s brief.'),('What evidence do you have?','People repeatedly ask me about a specific problem.','I can spot and improve a specific business deliverable.'),('What is your immediate constraint?','I need a manageable product I can finish and test.','I need a small service scope I can deliver confidently.')]
qs=''.join(f'<fieldset class="quiz-question"><legend>{i+1}. {E(q)}</legend><label><input type="radio" name="q{i}" value="product" required>{E(a)}</label><label><input type="radio" name="q{i}" value="service" required>{E(b)}</label></fieldset>' for i,(q,a,b) in enumerate(questions))
write('quiz.html','Find my track',hero('Six decisions · no income prediction','Choose the route you can execute.','This is a preference guide, not a forecast. Answer all six questions. Your selected route saves to your account and takes you to the matching steps.')+f'<form id="track-quiz">{qs}<button>Get and save my track</button></form><section class="track-panel" id="quiz-result" hidden aria-live="polite"></section><p class="status" id="quiz-status" role="status"></p>')
