fields=[('plan-cost','Monthly plan cost in your currency',0),('credits','Credits available',1000),('attempt-cost','Credits per attempt',10),('attempts','Attempts per accepted shot',3),('shots','Generated shots per finished edit',2),('extra','Other credits per finished edit',0)]
ff=''.join(f'<label>{label}<input id="{key}" type="number" min="0" step="any" value="{value}" required></label>' for key,label,value in fields)
write('tools.html','Tools and costs',hero('Spending routes · checked 6 October 2026','Use the smallest stack that delivers.','Start with one writing tool, one editor, and one delivery method. These are optional tools, not required subscriptions. Check current plan terms and regional availability before paying.')+f'<section class="section"><div class="grid">{tc}</div></section><section class="section" id="calculator"><h2>How many usable video edits can your budget support?</h2><p>The starting numbers are hypothetical, not a Higgsfield plan. Enter the actual displayed cost, expected retries, and generated shots per edit. Count image generation, upscales, and other credit costs. Real capacity may be lower.</p><form id="credit-calculator"><div class="field-grid">{ff}</div><div class="output" id="credit-result" aria-live="polite"></div></form><p class="muted">Credits per edit = attempt cost × attempts × generated shots + other credits. Estimated edits = floor(credits available ÷ credits per edit). Subscription cost per estimated edit = plan cost ÷ edits. This excludes labor, taxes, separate plans, and failed work beyond your retry estimate.</p></section><section class="section"><h2>A free workflow you can run today.</h2><ol><li>Collect verified business facts and approved photos.</li><li>Draft with ChatGPT or Claude Free. Save the output and edit it yourself.</li><li>Make three designs with free Canva assets, or film your screen and own voice.</li><li>Use Pexels only for supporting imagery with the license checked.</li><li>Add captions manually if your editor’s automatic captions require a subscription.</li><li>Deliver through a shareable folder and test access in another browser session.</li></ol><a href="/playbooks/playbook-f-content-service.html">Follow the complete salon delivery →</a></section>')
